typedef long unsigned size_t;

size_t size_t_var;  // Declares a variable

// Shadowing: Variable hides the type
struct size_t { int x; };
struct size_t size_t_struct;

// size_t refers to the structure here
sizeof(size_t);
typedef struct size_t size_t_t; // Renaming the struct type

// Correct interpretation using 'struct' keyword
struct size_t size_t;
// size_t (variable) is 4 bytes
// struct size_t (type) is also 4 bytes (e.g.)

// Global scope vs local scope shadowing
void f() {
    typedef int size_t;
    size_t local_var;  // int type
}
